#include <Aevrynd/PhysicsWorld3D.h>
#include <algorithm>
#include <cmath>

namespace Aevrynd {
namespace {
Vec3 PositiveExtents(Vec3 value){return{(std::max)(.001f,std::abs(value.x)),(std::max)(.001f,std::abs(value.y)),(std::max)(.001f,std::abs(value.z))};}
float& AxisReference(Vec3& value,int axis){return axis==0?value.x:axis==1?value.y:value.z;}
float AxisValue(Vec3 value,int axis){return axis==0?value.x:axis==1?value.y:value.z;}
}

RigidBodyHandle3D PhysicsWorld3D::CreateBody(RigidBodySettings3D settings){settings.colliderExtents=PositiveExtents(settings.colliderExtents);settings.mass=(std::max)(.001f,settings.mass);settings.gravityScale=(std::max)(0.f,settings.gravityScale);settings.material.friction=Clamp(settings.material.friction,0.f,1.f);settings.material.restitution=Clamp(settings.material.restitution,0.f,1.f);const RigidBodyHandle3D handle{nextHandle_++};bodies_.emplace(handle.value,RigidBodyState3D{handle,settings});return handle;}
bool PhysicsWorld3D::DestroyBody(RigidBodyHandle3D handle){return bodies_.erase(handle.value)>0;}
void PhysicsWorld3D::Clear(){std::unordered_map<uint32_t,RigidBodyState3D>{}.swap(bodies_);stats_={};}
RigidBodyState3D* PhysicsWorld3D::GetBody(RigidBodyHandle3D handle){const auto found=bodies_.find(handle.value);return found==bodies_.end()?nullptr:&found->second;}
const RigidBodyState3D* PhysicsWorld3D::GetBody(RigidBodyHandle3D handle)const{const auto found=bodies_.find(handle.value);return found==bodies_.end()?nullptr:&found->second;}
bool PhysicsWorld3D::SetTransform(RigidBodyHandle3D handle,Transform3D transform,bool wake){RigidBodyState3D* body=GetBody(handle);if(!body)return false;body->settings.transform.position=transform.position;body->settings.transform.rotation=transform.rotation;if(wake){body->sleeping=false;body->sleepClock=0;}return true;}
bool PhysicsWorld3D::SetVelocity(RigidBodyHandle3D handle,Vec3 velocity){RigidBodyState3D* body=GetBody(handle);if(!body||body->settings.type==RigidBodyType3D::Static)return false;body->velocity=velocity;body->sleeping=false;body->sleepClock=0;return true;}
bool PhysicsWorld3D::AddForce(RigidBodyHandle3D handle,Vec3 force){RigidBodyState3D* body=GetBody(handle);if(!body||body->settings.type!=RigidBodyType3D::Dynamic)return false;body->accumulatedForce=body->accumulatedForce+force;body->sleeping=false;return true;}
bool PhysicsWorld3D::ApplyImpulse(RigidBodyHandle3D handle,Vec3 impulse){RigidBodyState3D* body=GetBody(handle);if(!body||body->settings.type!=RigidBodyType3D::Dynamic)return false;body->velocity=body->velocity+impulse*(1.f/body->settings.mass);body->sleeping=false;body->sleepClock=0;return true;}
bool PhysicsWorld3D::LayersMatch(const RigidBodyState3D& left,const RigidBodyState3D& right){return(left.settings.layer&right.settings.collisionMask)&&(right.settings.layer&left.settings.collisionMask);}
bool PhysicsWorld3D::Overlaps(const RigidBodyState3D& left,const RigidBodyState3D& right){const Vec3 delta=left.settings.transform.position-right.settings.transform.position,a=left.settings.colliderExtents,b=right.settings.colliderExtents;return std::abs(delta.x)<a.x+b.x&&std::abs(delta.y)<a.y+b.y&&std::abs(delta.z)<a.z+b.z;}
void PhysicsWorld3D::ResolveAxis(RigidBodyState3D& body,float deltaTime,int axis){float& position=AxisReference(body.settings.transform.position,axis);float& velocity=AxisReference(body.velocity,axis);position+=velocity*deltaTime;for(auto& [id,obstacle]:bodies_){if(id==body.handle.value||obstacle.settings.type==RigidBodyType3D::Dynamic||!LayersMatch(body,obstacle))continue;++stats_.broadPhaseTests;if(!Overlaps(body,obstacle))continue;++stats_.contacts;const float side=velocity>0?-1.f:velocity<0?1.f:(AxisValue(body.settings.transform.position,axis)>=AxisValue(obstacle.settings.transform.position,axis)?1.f:-1.f);position=AxisValue(obstacle.settings.transform.position,axis)+side*(AxisValue(obstacle.settings.colliderExtents,axis)+AxisValue(body.settings.colliderExtents,axis));const float restitution=(std::max)(body.settings.material.restitution,obstacle.settings.material.restitution);velocity=-velocity*restitution;if(std::abs(velocity)<.08f)velocity=0;const float friction=1.f-Clamp((body.settings.material.friction+obstacle.settings.material.friction)*.5f*deltaTime*9.f,0.f,.92f);if(axis==1){body.velocity.x*=friction;body.velocity.z*=friction;}}
}
void PhysicsWorld3D::Step(float deltaTime,unsigned substeps){deltaTime=Clamp(deltaTime,0.f,.1f);substeps=(std::max)(1u,substeps);const float step=deltaTime/float(substeps);++stats_.steps;stats_.substeps+=substeps;for(unsigned substep=0;substep<substeps;++substep)for(auto& [id,body]:bodies_){(void)id;if(body.settings.type!=RigidBodyType3D::Dynamic||body.sleeping)continue;body.velocity=body.velocity+(gravity_*body.settings.gravityScale+body.accumulatedForce*(1.f/body.settings.mass))*step;ResolveAxis(body,step,0);ResolveAxis(body,step,2);ResolveAxis(body,step,1);const float speedSquared=Dot(body.velocity,body.velocity);if(body.settings.allowSleep&&speedSquared<.0025f){body.sleepClock+=step;if(body.sleepClock>=.55f){body.sleeping=true;body.velocity={};++stats_.sleepTransitions;}}else body.sleepClock=0;}for(auto& [id,body]:bodies_){(void)id;body.accumulatedForce={};}}
PhysicsWorldStats3D PhysicsWorld3D::Stats()const{PhysicsWorldStats3D result=stats_;result.bodies=bodies_.size();for(const auto& [id,body]:bodies_){(void)id;if(body.settings.type==RigidBodyType3D::Static)++result.staticBodies;else if(body.settings.type==RigidBodyType3D::Dynamic)++result.dynamicBodies;else ++result.kinematicBodies;if(body.sleeping)++result.sleepingBodies;}return result;}
}
